"""Small geometry helpers shared by the press part builders."""
import math

import cadquery as cq


def shape_of(obj):
    return obj.val() if isinstance(obj, cq.Workplane) else obj


def compound(objects):
    shapes = []
    for obj in objects:
        shape = shape_of(obj)
        if shape is not None:
            shapes.append(shape)
    return cq.Compound.makeCompound(shapes)


def box(length, width, height, center_x, center_y, bottom_z):
    return cq.Solid.makeBox(
        length, width, height,
        cq.Vector(center_x - length / 2.0, center_y - width / 2.0, bottom_z),
    )


def cylinder(radius, height, base, direction=(0.0, 0.0, 1.0)):
    return cq.Solid.makeCylinder(
        radius, height, cq.Vector(*base), cq.Vector(*direction)
    )


def rod_between(start, end, radius):
    delta = tuple(end[i] - start[i] for i in range(3))
    length = math.sqrt(sum(v * v for v in delta))
    direction = tuple(v / length for v in delta)
    return cylinder(radius, length, start, direction)


def sphere(radius, center):
    return cq.Solid.makeSphere(radius, cq.Vector(*center))


def xz_cylinder(radius, length, x, y_high, z):
    """Y-axis cylinder, starting at y_high and extending toward negative Y."""
    return cylinder(radius, length, (x, y_high, z), (0.0, -1.0, 0.0))


def hex_xz(across_corners, depth, x, y_high, z):
    return (
        cq.Workplane("XZ", origin=(0.0, y_high, 0.0))
        .center(x, z)
        .polygon(6, across_corners)
        .extrude(depth)
        .val()
    )

