export function hashed(n) { return ((Math.sin(n * 127.1) * 43758.5453) % 1 + 1) % 1; }
export function polygon(ctx, pts, close = true) {
  ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]));
