:root {
  color-scheme: dark;
  --ink: #151c24;
  --ink-deep: #111820;
  --panel: #1b242d;
  --panel-soft: #202a33;
  --ivory: #e9dfc7;
  --ivory-soft: #c8c2b1;
  --muted: #89928e;
  --line: #354048;
  --blue: #79aeca;
  --orange: #d99457;
  --green: #7fa983;
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-synthesis: none;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
body { background: var(--ink); color: var(--ivory); }
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible {
  outline: 2px solid #add8e0;
  outline-offset: 3px;
}
button { -webkit-tap-highlight-color: transparent; }

.app-shell {
  width: 100vw;
  height: 100dvh;
  min-height: 540px;
  display: grid;
  grid-template-rows: 46px minmax(0, 1fr) 106px;
  background: var(--ink);
}

.topbar {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  border-bottom: 1px solid #2c3740;
  background: #151c24;
  box-shadow: 0 2px 10px #080d1250;
}
.topbar h1 {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: max-content;
  margin: 0;
  font-size: 15px;
  font-weight: 450;
  letter-spacing: .035em;
  color: #e2d8c3;
}
.menu-mark {
  width: 34px;
  height: 30px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 5px 4px;
  border: 0;
  background: transparent;
  cursor: pointer;
  border-radius: 3px;
}
.menu-mark:hover { background: #ffffff08; }
.menu-mark span { width: 16px; height: 1px; background: #d8d3c5; }
.live-status { display: flex; align-items: center; gap: 8px; font-size: 13px; color: #d8ddce; }
.live-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #54b76b;
  box-shadow: 0 0 8px #54b76b55, 0 0 0 3px #54b76b12;
}

.main-workspace {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 2.04fr) minmax(390px, 1fr);
}
.stage-panel {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-right: 1px solid #3a4248;
  background-color: #1e2932;
}
.blueprint-grid {
  background-image:
    linear-gradient(#7f9ca610 1px, transparent 1px),
    linear-gradient(90deg, #7f9ca610 1px, transparent 1px),
    linear-gradient(#a7cad008 1px, transparent 1px),
    linear-gradient(90deg, #a7cad008 1px, transparent 1px),
    radial-gradient(ellipse at 51% 44%, #293741 0%, #1f2b34 49%, #1a252e 100%);
  background-size: 32px 32px, 32px 32px, 8px 8px, 8px 8px, 100% 100%;
}
.stage-panel::after {
  content: "";
  position: absolute;
  inset: 11px;
  border: 1px solid #a7bec706;
  pointer-events: none;
}
.stage-kicker {
  position: absolute;
  top: 19px;
  left: 25px;
  right: 25px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 9px;
  color: #b3bdb7;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .14em;
  pointer-events: none;
}
.section-index {
  color: #d9cfb7;
