  color: #788b92;
  font-size: 8px;
  letter-spacing: .13em;
  pointer-events: none;
}
.stage-notation span { padding: 0 8px; color: #c9c0aa; }
.engine-stage { position: absolute; inset: 36px 6px 30px; }
#stage { display: block; width: 100%; height: 100%; }
.stage-footer {
  position: absolute;
  z-index: 2;
  bottom: 13px;
  left: 26px;
  right: 25px;
  display: flex;
  gap: 25px;
  align-items: center;
  color: #879a9e;
