.wheel-block { min-width: 0; min-height: 0; display: flex; flex-direction: column; padding: 10px 10px 8px 13px; }
.wheel-block h2 { margin: 0 0 3px; font-size: 11px; font-weight: 450; color: #d7d0bc; white-space: nowrap; }
.wheel-block h2 span { display: block; font-size: 8px; color: #788c93; text-transform: uppercase; letter-spacing: .13em; margin-top: 3px; }
.phase-wheel { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; }
#phase-svg { width: 100%; height: 100%; display: block; overflow: visible; }
.wheel-caption { display: flex; justify-content: space-between; padding: 1px 2px 0; font-size: 7px; color: #71858c; letter-spacing: .09em; }
