.telemetry { border-left: 1px solid #354149; display: grid; grid-template-rows: repeat(4, minmax(0, 1fr)); min-height: 0; }
.telemetry-item { min-height: 0; display: flex; flex-direction: column; justify-content: center; padding: 5px 14px; border-bottom: 1px solid #303b43; }
.telemetry-item:last-child { border-bottom: 0; }
.readout-value {
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  color: #e7dcc3;
  font-size: clamp(23px, 2.35vw, 34px);
