  letter-spacing: -.035em;
  white-space: nowrap;
}
.rpm-readout .readout-value { font-size: clamp(25px, 2.5vw, 37px); }
.readout-value > span { font-size: .45em; letter-spacing: .015em; padding-left: 4px; }
.readout-label { margin-top: 5px; font-size: 10px; color: #d9d3c2; line-height: 1; }
.readout-label > span { display: block; color: #6e848e; font-size: 6.5px; letter-spacing: .11em; margin-top: 4px; }

.control-rail {
  position: relative;
  z-index: 4;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1.95fr) minmax(0, 1.6fr);
  gap: 26px;
  padding: 13px 22px 11px;
  border-top: 1px solid #3a4146;
  background: #18212a;
  box-shadow: 0 -4px 18px #0b10152a;
}
.control-group { min-width: 0; display: flex; flex-direction: column; }
.control-heading { min-height: 25px; display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.control-heading > label, .control-heading > span:first-child {
