}
.control-heading output { color: #ded4bb; font-size: 11px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.control-heading output span { color: #71878e; font-size: 7px; letter-spacing: .08em; }
.instrument-slider, #scrub { width: 100%; margin: 7px 0 0; cursor: pointer; }
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  height: 14px;
  background: transparent;
  border: 0;
}
input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 1px;
  background: linear-gradient(90deg, #b7b6a4 var(--fill, 100%), #34414a var(--fill, 100%));
}
input[type="range"]::-moz-range-track { height: 4px; border-radius: 1px; background: #34414a; }
input[type="range"]::-moz-range-progress { height: 4px; background: #b7b6a4; }
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  margin-top: -4.5px;
  background: #ddd2b8;
  border: 1px solid #eee3c9;
  box-shadow: 0 0 0 3px #172029;
}
input[type="range"]::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ddd2b8;
  border: 1px solid #eee3c9;
  box-shadow: 0 0 0 3px #172029;
}
.range-labels { display: flex; justify-content: space-between; color: #657b86; font-size: 7px; letter-spacing: .065em; margin-top: 1px; }
.inspector-status { color: #7f938e; font-size: 7px; letter-spacing: .08em; white-space: nowrap; padding-top: 4px; }
.stroke-buttons { display: grid; grid-template-columns: .88fr 1.38fr .88fr 1fr .54fr; gap: 4px; margin-top: 7px; }
.stroke-buttons button {
  min-width: 0;
  height: 28px;
  padding: 0 5px;
  border: 1px solid #3a464c;
  background: #1e2931;
  color: #c9c5b7;
  font-size: 9px;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color .12s, color .12s, border-color .12s;
}
.stroke-buttons button > span { display: none; }
.stroke-buttons button:hover { border-color: #788783; background: #2c373c; }
.stroke-buttons button.active, .stroke-buttons button[aria-pressed="true"] {
  background: #ded3b8;
  border-color: #e7dcc2;
  color: #263038;
  box-shadow: inset 0 -2px #8c927f;
}
.transport { display: flex; gap: 5px; margin-top: -4px; }
.transport button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 47px;
  height: 22px;
  border: 1px solid #3d4b51;
  border-radius: 2px;
