  cursor: pointer;
}
.transport button:hover { background: #344047; color: #efe3ca; }
.transport button.active { border-color: #899b8a; color: #eee2c5; background: #334139; }
.play-symbol { font-size: 6px; }
.pause-symbol { font-size: 9px; letter-spacing: -1px; }
.scrub-track { position: relative; margin-top: 5px; }
.cycle-ticks { position: absolute; left: 0; right: 0; top: 5px; height: 9px; display: grid; grid-template-columns: repeat(4, 1fr); pointer-events: none; }
.cycle-ticks i { border-left: 1px solid #8a999644; }
.cycle-ticks i:last-child { border-right: 1px solid #8a999644; }
#scrub { position: relative; margin: 0; }
.cycle-readout { display: flex; justify-content: space-between; font-size: 7px; color: #7d9197; letter-spacing: .07em; margin-top: 1px; }
#active-stroke { color: #c9c3b1; }

#stage text { user-select: none; }
.engine-label { fill: #d5d1bd; font-size: 11px; font-family: "Segoe UI", Arial, sans-serif; letter-spacing: .015em; }
.engine-label-small { fill: #7e949a; font-size: 7.5px; font-family: "Segoe UI", Arial, sans-serif; letter-spacing: .11em; }
.leader { stroke: #a8b8b1; stroke-width: .8; fill: none; opacity: .75; }
.leader-dot { fill: #e5dbc0; stroke: #27343a; stroke-width: 1; }

@media (min-height: 800px) {
  .app-shell { grid-template-rows: 50px minmax(0, 1fr) 116px; }
