    const p2 = polar(130, 130, 106, a);
    ticks.push(`<path d="M${pointString(p1)}L${pointString(p2)}" stroke="${i % 18 === 0 ? '#9ea894' : '#647974'}" stroke-width="${i % 18 === 0 ? 1 : .6}"/>`);
