import { WORLD, TAU, cyclicTime, clamp, pulseAt } from './utils.js';
import { drawSky, drawOceanBase, drawWaveLayer, drawRain, drawSeaMist, drawLightOnSea } from './environment.js';
import { drawBreakwater, drawShip, drawBuoy } from './vessel.js';
import { computeOptics, drawBeam, drawLighthouse } from './mechanics.js';

export const DEFAULTS = Object.freeze({ t: 0, day: 0, storm: .78, elevation: 28 });

export function getReadings(scene) {
  const pulseAge = Number.isFinite(scene.pulse.age) ? scene.pulse.age : 0;
  const pulseWave = scene.pulse.envelope * Math.sin(pulseAge * 17) * .7;
  const wave = 1 + scene.storm * (3.8 / .78) + pulseWave;
  const period = 5.8 + scene.storm * (1.4 / .78) + scene.pulse.envelope * Math.sin(pulseAge * 11) * .15;
  const knots = Math.round(scene.storm * (42 / .78));
  const lamp = Math.round(clamp(.89 - scene.day * .38 + scene.pulse.envelope * .09, .18, 1) * 100);
  return { wave, period, knots, lamp };
}

function drawTelemetry(ctx, scene) {
  const c = ctx.canvas, w = c.width, h = c.height;
  ctx.clearRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(92,123,139,.15)'; ctx.lineWidth = 1;
  for (let y = 6; y < h; y += 12) { ctx.beginPath(); ctx.moveTo(0, y + .5); ctx.lineTo(w, y + .5); ctx.stroke(); }
  for (let x = 0; x < w; x += 50) { ctx.beginPath(); ctx.moveTo(x + .5, 0); ctx.lineTo(x + .5, h); ctx.stroke(); }
  const gradient = ctx.createLinearGradient(0, 0, w, 0);
  gradient.addColorStop(0, 'rgba(90,167,183,.3)'); gradient.addColorStop(.7, '#77c3cd'); gradient.addColorStop(1, scene.pulse.envelope > .03 ? '#f0c17c' : '#a5d6d8');
  ctx.beginPath();
  for (let x = 0; x <= w; x += 2) {
    const q = x / w;
    const carrier = Math.sin(q * TAU * 3 + scene.t / 8 * TAU * 3) * (2.1 + scene.storm * 3.3);
    const secondary = Math.sin(q * TAU * 9 - scene.t / 8 * TAU * 2) * scene.storm * 1.1;
    const pulseWave = scene.pulse.envelope * Math.exp(-Math.pow((q - .81) * 10, 2)) * Math.sin(q * 92 - (Number.isFinite(scene.pulse.age) ? scene.pulse.age : 0) * 15) * 10;
    const y = h * .51 + carrier + secondary + pulseWave;
    if (!x) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.strokeStyle = gradient; ctx.lineWidth = 1.6; ctx.stroke();
  ctx.strokeStyle = 'rgba(145,215,217,.07)'; ctx.lineWidth = 5; ctx.stroke();
}

export class TidalScene {
  constructor(canvas, telemetryCanvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.telemetry = telemetryCanvas?.getContext('2d');
    this.cssWidth = 0; this.cssHeight = 0;
    this.resize();
  }
  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(rect.width * dpr)), h = Math.max(1, Math.round(rect.height * dpr));
    if (this.canvas.width !== w || this.canvas.height !== h) { this.canvas.width = w; this.canvas.height = h; }
    this.cssWidth = rect.width; this.cssHeight = rect.height; this.dpr = dpr;
  }
  render(input) {
    this.resize();
    const scene = {
      t: cyclicTime(input.t), day: clamp(input.day), storm: clamp(input.storm),
      elevation: clamp(input.elevation, 0, 90),
    };
    scene.pulse = pulseAt(scene.t, input.pulseStart);
    scene.optics = computeOptics(scene);
    const ctx = this.ctx, cw = this.canvas.width, ch = this.canvas.height;
    ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#10233a'; ctx.fillRect(0, 0, cw, ch);
    const scale = Math.max(cw / WORLD.width, ch / WORLD.height);
    const tx = (cw - WORLD.width * scale) * .5, ty = (ch - WORLD.height * scale) * .5;
    ctx.setTransform(scale, 0, 0, scale, tx, ty);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';

    drawSky(ctx, scene);
    drawOceanBase(ctx, scene);
    drawRain(ctx, scene, false);
    drawSeaMist(ctx, scene);
    drawWaveLayer(ctx, scene, 0);
    drawBreakwater(ctx, scene);
    drawWaveLayer(ctx, scene, 1);
    drawWaveLayer(ctx, scene, 2);
    drawShip(ctx, scene);
    drawLightOnSea(ctx, scene, scene.optics);
    drawBuoy(ctx, scene, scene.optics, 1);
    drawBuoy(ctx, scene, scene.optics, 0);
    drawBeam(ctx, scene, scene.optics);
    drawLighthouse(ctx, scene, scene.optics);
    drawRain(ctx, scene, true);

    // Keep full-canvas state clean for exact out-of-order redraws.
    ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    if (this.telemetry) drawTelemetry(this.telemetry, scene);
    return scene;
  }
}

import { TidalScene, DEFAULTS, getReadings } from './scene.js';
import { cyclicTime, clamp, formatTime } from './utils.js';

const $ = id => document.getElementById(id);
const state = { ...DEFAULTS, pulseStart: null, playing: true };
const tidal = new TidalScene($('canvas'), $('telemetry-canvas'));
let lastNow = performance.now();
let latestScene = null;

function utcForDay(day) {
  const minutes = ((22 * 60 + 38 + Math.round(day * 14 * 60)) % 1440 + 1440) % 1440;
  return `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')} UTC`;
}
function paintRange(input) {
  const value = (+input.value - +input.min) / (+input.max - +input.min) * 100;
  input.style.setProperty('--fill', `${value}%`);
}
function syncUI(scene) {
  $('day-night-slider').value = String(state.day);
  $('storm-slider').value = String(state.storm);
  $('beam-elevation').value = String(state.elevation);
  $('beam-value').value = `${Math.round(state.elevation)}°`;
  $('day-value').value = state.day < .18 ? 'NIGHT' : state.day < .43 ? 'DAWN' : state.day < .72 ? 'DAYLIGHT' : 'GOLDEN';
  $('storm-value').value = `${Math.round(state.storm * 100)}%`;
  $('weather-status').textContent = state.storm < .18 ? 'CALM' : state.storm < .45 ? 'BREEZE' : state.storm < .72 ? 'SQUALL' : 'STORM';
  $('utc-time').textContent = utcForDay(state.day);
  $('dial-needle').style.transform = `rotate(${-135 + state.elevation / 90 * 270}deg)`;
  $('scrub').value = String(state.t);
  $('timecode').innerHTML = `${formatTime(state.t)} <span>/ 00:08.00</span>`;
  $('play-state').textContent = state.playing ? 'RUNNING' : 'PAUSED';
  $('play').setAttribute('aria-pressed', String(state.playing));
  $('pause').setAttribute('aria-pressed', String(!state.playing));
  document.querySelector('.loop-state i').style.background = state.playing ? '#89c8ad' : '#a49379';
  $('foghorn-btn').classList.toggle('is-pulsing', scene.pulse.envelope > .035);
  const readings = getReadings(scene);
  $('wave-reading').innerHTML = `${readings.wave.toFixed(1)} m <span>|</span> ${readings.period.toFixed(1)} s`;
  $('wave-reading').classList.toggle('pulse', scene.pulse.envelope > .04);
  $('wind-reading').innerHTML = `${readings.knots} kts <span>${scene.storm < .18 ? 'W' : 'WNW'}</span>`;
  $('lamp-reading').textContent = `${readings.lamp}% POWER`;
  $('tide-reading').innerHTML = `EBBING <b>↘</b>`;
  for (const id of ['day-night-slider', 'storm-slider', 'beam-elevation', 'scrub']) paintRange($(id));
}

function render() {
  latestScene = tidal.render(state);
  syncUI(latestScene);
}
function seek(value, pause = true) {
  state.t = cyclicTime(value);
  if (pause) state.playing = false;
  lastNow = performance.now();
  render();
}

$('play').addEventListener('click', () => { state.playing = true; lastNow = performance.now(); render(); });
$('pause').addEventListener('click', () => { state.playing = false; lastNow = performance.now(); render(); });
$('scrub').addEventListener('input', event => seek(+event.target.value));
$('day-night-slider').addEventListener('input', event => { state.day = clamp(+event.target.value); render(); });
$('storm-slider').addEventListener('input', event => { state.storm = clamp(+event.target.value); render(); });
$('beam-elevation').addEventListener('input', event => { state.elevation = clamp(+event.target.value, 0, 90); render(); });
$('foghorn-btn').addEventListener('click', () => { state.pulseStart = state.t; lastNow = performance.now(); render(); });
function reset() {
  Object.assign(state, DEFAULTS, { pulseStart: null, playing: false });
  lastNow = performance.now(); render();
}
$('reset-btn').addEventListener('click', reset);
window.addEventListener('keydown', event => {
  if (event.key.toLowerCase() === 'r' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName || '')) reset();
  if (event.code === 'Space' && !/INPUT|BUTTON/.test(document.activeElement?.tagName || '')) {
    event.preventDefault(); state.playing = !state.playing; lastNow = performance.now(); render();
  }
});
window.addEventListener('resize', render);

window.renderAt = async seconds => {
  seek(seconds, true);
  return window.__getSceneState();
};
window.__getSceneState = () => ({
  t: state.t, time: state.t, duration: 8, playing: state.playing,
  day: state.day, dayNight: state.day, night: 1 - state.day,
  storm: state.storm, stormIntensity: state.storm,
  elevation: state.elevation, beamElevation: state.elevation,
  pulseStart: state.pulseStart,
  beaconPulse: latestScene?.pulse.envelope || 0,
  foghornPulse: latestScene?.pulse.envelope || 0,
  pulseAge: Number.isFinite(latestScene?.pulse.age) ? latestScene.pulse.age : null,
  utc: utcForDay(state.day),
  readings: latestScene ? getReadings(latestScene) : null,
  periodic: true,
});

function frame(now) {
  const dt = Math.min((now - lastNow) / 1000, .12);
  lastNow = now;
  if (state.playing) { state.t = cyclicTime(state.t + dt); render(); }
  requestAnimationFrame(frame);
}
render();
window.__SCENE_READY__ = true;
requestAnimationFrame(frame);

export const TAU = Math.PI * 2;
export const DURATION = 8;
export const WORLD = { width: 1200, height: 760, horizon: 354 };
export const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smooth = t => { t = clamp(t); return t * t * (3 - 2 * t); };
export const mod = (n, m) => ((n % m) + m) % m;
export const cyclicTime = t => mod(Number.isFinite(+t) ? +t : 0, DURATION);
export function seeded(seed = 18) {
  let s = seed >>> 0;
  return () => { s = (Math.imul(1664525, s) + 1013904223) >>> 0; return s / 4294967296; };
}
export function hexMix(a, b, t) {
  const p = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const A = p(a), B = p(b);
  return `rgb(${Math.round(lerp(A[0], B[0], t))},${Math.round(lerp(A[1], B[1], t))},${Math.round(lerp(A[2], B[2], t))})`;
}
export function path(ctx, points, close = true) {
  ctx.beginPath();
  points.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]));
  if (close) ctx.closePath();
}
export function strokePath(ctx, points, color, width = 1, close = false) {
  path(ctx, points, close); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
}
export function circle(ctx, x, y, r, fill, stroke = null, width = 1) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
}
export function line(ctx, x1, y1, x2, y2, color, width = 1) {
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
}
export function glow(ctx, x, y, radius, inner, outer = 'rgba(0,0,0,0)') {
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, inner); g.addColorStop(1, outer);
  ctx.fillStyle = g; ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
}
export function pulseAt(t, startedAt) {
  if (startedAt == null) return { age: Infinity, strength: 0, envelope: 0 };
  const age = mod(t - startedAt, DURATION);
  const envelope = age < 3.4 ? Math.exp(-age * 1.25) : 0;
  return { age, strength: envelope * (0.72 + 0.28 * Math.cos(age * 17)), envelope };
}
export function formatTime(seconds) {
  const s = clamp(seconds, 0, DURATION);
  return `00:${String(Math.floor(s)).padStart(2, '0')}.${String(Math.floor((s % 1) * 100)).padStart(2, '0')}`;
}

import { TAU, clamp, lerp, path, line, circle, glow, hexMix } from './utils.js';
import { waveY } from './environment.js';

export function drawBreakwater(ctx, scene) {
  const { day } = scene;
  ctx.save();
  const wall = path(ctx, [[-40, 470], [488, 412], [546, 430], [548, 493], [-40, 568]]);
  ctx.fillStyle = hexMix('#34434a', '#737f7b', day); ctx.fill();
  ctx.strokeStyle = '#142837'; ctx.lineWidth = 2.4; ctx.stroke();
  const top = path(ctx, [[-40, 457], [476, 402], [548, 424], [544, 439], [487, 421], [-40, 480]]);
  ctx.fillStyle = hexMix('#52636b', '#93a098', day); ctx.fill(); ctx.stroke();
  ctx.save(); path(ctx, [[-40, 470], [488, 412], [546, 430], [548, 493], [-40, 568]]); ctx.clip();
  for (let row = 0; row < 6; row++) {
    const y = 422 + row * 23;
    line(ctx, -20, y + 55, 562, y - 6, '#172b36', 1.2);
    for (let col = -1; col < 14; col++) {
      const x = col * 49 + (row % 2) * 25;
      line(ctx, x, y + 58, x + 4, y + 31, '#1e3440', .9);
      line(ctx, x + 5, y + 31, x + 46, y + 26, 'rgba(131,151,151,.16)', .7);
    }
  }
  ctx.restore();
  // The rear channel marker is deliberately much smaller than the two foreground buoys.
  ctx.fillStyle = '#4a5a5c'; ctx.fillRect(473, 389, 18, 30);
  ctx.fillStyle = '#718481'; path(ctx, [[468, 389], [482, 382], [496, 389]]); ctx.fill();
  ctx.fillStyle = '#3f565d'; path(ctx, [[479, 382], [480, 327], [485, 320], [490, 328], [490, 383]]); ctx.fill();
  ctx.strokeStyle = '#192e3b'; ctx.lineWidth = 1.5; ctx.stroke();
  line(ctx, 475, 382, 475, 417, '#96aaa4', 1);
  line(ctx, 477, 337, 492, 337, '#789299', 1);
  const beacon = .4 + scene.pulse.envelope * .6;
  glow(ctx, 486, 324, 16, `rgba(244,165,106,${.13 * beacon})`);
  circle(ctx, 486, 324, 2.1, `rgba(245,178,110,${beacon})`, '#2d4249', .8);
  ctx.restore();
}

function sailPath(ctx, points, fill, stroke = '#172d3a') {
  path(ctx, points); ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = stroke; ctx.lineWidth = 1.8; ctx.stroke();
}

function drawSailSeams(ctx, start, end, count, curve = 0) {
  for (let i = 1; i < count; i++) {
    const q = i / count;
    const x1 = lerp(start[0], end[0], q), y1 = lerp(start[1], end[1], q);
    ctx.beginPath(); ctx.moveTo(x1, y1);
    ctx.quadraticCurveTo(x1 + curve, y1 + 38, lerp(start[0], end[0], q) + 5, end[1]);
    ctx.strokeStyle = 'rgba(26,54,65,.29)'; ctx.lineWidth = .7; ctx.stroke();
  }
}

export function drawShip(ctx, scene) {
  const { t, storm, day, pulse } = scene;
  const p = t / 8 * TAU;
  const sea = waveY(320, 1, t, storm);
  const heave = Math.sin(p * 2 + .7) * (2.5 + storm * 7.2) + (sea - 431) * .22;
  const pitch = Math.sin(p * 2 + 1.1) * (.012 + storm * .033) + Math.sin(p * 3) * storm * .006;
  ctx.save(); ctx.translate(318, 517 + heave); ctx.rotate(pitch); ctx.scale(1.02, 1.02);

  // A broken reflection travels with the same hull transform, avoiding a detached shadow.
  ctx.save(); ctx.translate(0, 72); ctx.scale(1, -.23); ctx.globalAlpha = .18;
  path(ctx, [[-165, 0], [170, 0], [118, 55], [-97, 65]]); ctx.fillStyle = '#031b2b'; ctx.fill(); ctx.restore();

  // Rear rigging, masts and spars.
  line(ctx, -159, 49, -73, -276, '#101f2b', 1.1);
  line(ctx, -73, -276, 178, 34, '#142633', 1);
  line(ctx, 54, -251, -149, 42, '#142633', 1.1);
  line(ctx, 54, -251, 192, 27, '#142633', 1.3);
  line(ctx, -73, -267, 57, -248, '#233741', .8);
  line(ctx, -77, -279, -77, 35, '#17262c', 4.2);
  line(ctx, -75, -278, -75, 31, '#8c8064', 1.2);
  line(ctx, 52, -255, 52, 34, '#17262c', 4);
  line(ctx, 54, -252, 54, 32, '#8f8267', 1);
  line(ctx, -145, -192, -10, -179, '#372f29', 4);
  line(ctx, -144, -194, -9, -181, '#8d8169', 1);
  line(ctx, -5, -171, 110, -177, '#372f29', 4.2);
  line(ctx, -4, -173, 111, -179, '#938269', 1);
  line(ctx, -128, -76, -30, -67, '#393129', 3);
  line(ctx, 8, -57, 119, -42, '#393129', 3);

  // Three principal sails and two narrow staysails, all real Canvas paths.
  let sail = ctx.createLinearGradient(-90, -190, -30, -35);
  sail.addColorStop(0, hexMix('#688390', '#bbc5b9', day)); sail.addColorStop(.68, hexMix('#5b7e86', '#a7b5a7', day)); sail.addColorStop(1, hexMix('#b59c71', '#e4d5a7', day));
  sailPath(ctx, [[-140, -188], [-20, -178], [-26, -147], [-35, -94], [-42, -34], [-83, -50], [-124, -61]], sail);
  drawSailSeams(ctx, [-136, -185], [-48, -36], 6, -8);
  ctx.beginPath(); ctx.moveTo(-132, -177); ctx.quadraticCurveTo(-109, -98, -53, -46); ctx.strokeStyle = 'rgba(204,220,209,.15)'; ctx.lineWidth = 1.2; ctx.stroke();

  sail = ctx.createLinearGradient(25, -169, 71, -32);
  sail.addColorStop(0, hexMix('#738a91', '#c5cbbd', day)); sail.addColorStop(.75, hexMix('#6b8889', '#b0baa8', day)); sail.addColorStop(1, hexMix('#c3a470', '#ecdaad', day));
  sailPath(ctx, [[-1, -166], [102, -173], [102, -117], [96, -59], [87, 9], [37, -4], [10, -22]], sail);
  drawSailSeams(ctx, [5, -163], [22, -21], 7, 6);
  for (let i = 0; i < 4; i++) line(ctx, 10 + i * 20, -153, 22 + i * 16, -29, 'rgba(199,216,204,.12)', .8);

  sail = ctx.createLinearGradient(79, -179, 170, 27);
  sail.addColorStop(0, hexMix('#7d9499', '#c5cec2', day)); sail.addColorStop(1, hexMix('#a69877', '#e5d6b5', day));
  sailPath(ctx, [[59, -211], [186, 24], [104, 1], [78, -52]], sail);
  line(ctx, 65, -199, 166, 13, 'rgba(36,57,60,.28)', .8);
  sailPath(ctx, [[61, -147], [137, -1], [77, -16]], hexMix('#65848d', '#adbdb4', day));
  sailPath(ctx, [[-77, -265], [-123, -194], [-77, -204]], hexMix('#69878e', '#afbeb8', day));

  // Ratlines and front standing rigging.
  for (let i = 0; i < 8; i++) {
    const q = i / 8;
    line(ctx, -76 - 39 * q, -165 + 169 * q, -76 + 22 * q, -165 + 169 * q, 'rgba(18,36,43,.72)', .75);
  }
  line(ctx, -154, 30, 55, -249, 'rgba(18,34,42,.8)', .85);
  line(ctx, -51, 32, 193, 25, '#172c35', 1);
  line(ctx, 54, -246, 181, 28, '#182b32', .8);
  line(ctx, -76, -278, -93, -261, '#182b32', 1.3);
  path(ctx, [[-92, -262], [-113, -267], [-98, -274], [-92, -272]]); ctx.fillStyle = '#a46b52'; ctx.fill(); ctx.strokeStyle = '#26343b'; ctx.lineWidth = 1; ctx.stroke();

  // Hull shape, strakes and visibly planked deck.
  const hull = ctx.createLinearGradient(0, 12, 0, 87);
  hull.addColorStop(0, '#665641'); hull.addColorStop(.38, '#3e4038'); hull.addColorStop(1, '#162e37');
  path(ctx, [[-177, 21], [-148, 13], [-79, 18], [24, 15], [122, 7], [192, 24], [170, 47], [122, 72], [65, 84], [-88, 82], [-142, 62], [-164, 47]]);
  ctx.fillStyle = hull; ctx.fill(); ctx.strokeStyle = '#101f28'; ctx.lineWidth = 2.5; ctx.stroke();
  path(ctx, [[-177, 21], [-101, 30], [16, 25], [115, 15], [192, 24], [147, 28], [48, 34], [-85, 39], [-162, 32]]); ctx.fillStyle = '#807257'; ctx.fill(); ctx.strokeStyle = '#1b2d32'; ctx.lineWidth = 1.5; ctx.stroke();
  for (let i = 0; i < 5; i++) {
    ctx.beginPath(); ctx.moveTo(-155 + i * 3, 41 + i * 7); ctx.quadraticCurveTo(-15, 57 + i * 5, 151 - i * 9, 41 + i * 6);
    ctx.strokeStyle = i === 2 ? 'rgba(153,133,84,.48)' : 'rgba(15,30,35,.7)'; ctx.lineWidth = i === 2 ? 1.6 : 1; ctx.stroke();
  }
  for (let i = 0; i < 15; i++) {
    const x = -145 + i * 20;
    line(ctx, x, 34, x + 2, 45 + Math.sin(i) * 4, 'rgba(20,31,31,.5)', .8);
  }
  line(ctx, -178, 18, -88, 26, '#c0a574', 1.1); line(ctx, -86, 27, 185, 20, '#9a8968', 1);

  // Low aft cabin and its separate warm portholes.
  path(ctx, [[-143, 14], [-127, 0], [-52, 3], [-31, 18]]); ctx.fillStyle = '#58605a'; ctx.fill(); ctx.strokeStyle = '#172b33'; ctx.lineWidth = 1.5; ctx.stroke();
  path(ctx, [[-137, 13], [-125, 4], [-56, 6], [-43, 18]]); ctx.fillStyle = '#6c7160'; ctx.fill();
  const cabinPower = clamp(1 - day * .85 + pulse.envelope * .08);
  glow(ctx, -91, 30, 63, `rgba(242,173,75,${.1 * cabinPower})`);
  for (let i = 0; i < 10; i++) {
    const x = -139 + i * 16;
    const yy = 27 + Math.sin(i * .5) * 2;
    ctx.fillStyle = `rgba(255,200,96,${.34 + cabinPower * .66})`;
    ctx.fillRect(x, yy, 8, 7);
    ctx.strokeStyle = '#162931'; ctx.lineWidth = 1.4; ctx.strokeRect(x, yy, 8, 7);
    line(ctx, x + 4, yy, x + 4, yy + 7, '#795f36', .7);
    if (cabinPower > .25) glow(ctx, x + 4, yy + 3, 12, `rgba(255,183,69,${.08 * cabinPower})`);
  }
  // Bowsprit, stern lantern, helm and deck fittings.
  line(ctx, 131, 12, 202, 17, '#2b3030', 4); line(ctx, 133, 11, 202, 16, '#9f8965', 1);
  line(ctx, -163, 16, -163, -3, '#1c3034', 2);
  circle(ctx, -163, -5, 3, `rgba(250,186,80,${cabinPower})`, '#263438', 1);
  circle(ctx, -46, 10, 8, 'none', '#212e30', 2); circle(ctx, -46, 10, 2, '#8d7955');
  for (let i = 0; i < 6; i++) { const a = i / 6 * TAU; line(ctx, -46, 10, -46 + Math.cos(a) * 10, 10 + Math.sin(a) * 10, '#263339', .8); }
  // Foam lips around the hull are painted last, keeping the planking readable above the waterline.
  for (let i = 0; i < 7; i++) {
    const x = -163 + i * 48;
    const y = 70 + Math.sin(i * 1.7 + p * 2) * (2 + storm * 3);
    ctx.beginPath(); ctx.moveTo(x - 17, y + 3); ctx.quadraticCurveTo(x, y - 3, x + 25, y - 6);
    ctx.strokeStyle = `rgba(192,232,231,${.25 + storm * .48})`; ctx.lineWidth = 1 + storm * 1.6; ctx.stroke();
    if (storm > .3) circle(ctx, x + 14, y - 7, 1 + (i % 3) * storm, `rgba(208,239,235,${storm * .55})`);
  }
  ctx.restore();
}

export function getBuoyLight(optics, x, y) {
  const dx = optics.impact.x - optics.origin.x, dy = optics.impact.y - optics.origin.y;
  const len2 = dx * dx + dy * dy;
  const u = ((x - optics.origin.x) * dx + (y - optics.origin.y) * dy) / len2;
  if (u < .05 || u > 1.25) return 0;
  const px = optics.origin.x + dx * u, py = optics.origin.y + dy * u;
  const d = Math.hypot(x - px, y - py);
  const width = 35 + u * 95;
  return Math.exp(-(d * d) / (width * width)) * optics.strength;
}

export function drawBuoy(ctx, scene, optics, index) {
  const { t, storm, pulse, day } = scene;
  const p = t / 8 * TAU;
  const near = index === 0;
  const x = near ? 560 : 713;
  const water = near ? waveY(x, 1, t, storm) + 58 : waveY(x, 0, t, storm) + 72;
  const heave = Math.sin(p * (near ? 2 : 3) + (near ? .4 : 2.1)) * (near ? 3 : 2) * (.45 + storm);
  const tilt = Math.sin(p * 2 + (near ? 1.4 : .1)) * (.025 + storm * .10) * (near ? 1 : -1);
  const y = water + heave;
  const lit = clamp(getBuoyLight(optics, x, y - 30) * (1 - day * .55));
  const flash = clamp(pulse.envelope * (0.65 + .35 * Math.sin((Number.isFinite(pulse.age) ? pulse.age : 0) * 18)));
  ctx.save(); ctx.translate(x, y); ctx.rotate(tilt); ctx.scale(near ? 1 : .69, near ? 1 : .69);
  // Water contact belongs to the buoy's own frame but remains horizontally foreshortened.
  ctx.save(); ctx.scale(1.7, .25); ctx.beginPath(); ctx.arc(0, 4, 30, 0, TAU); ctx.strokeStyle = `rgba(183,230,225,${.24 + storm * .26})`; ctx.lineWidth = 1.8; ctx.stroke(); ctx.restore();
  path(ctx, [[-25, -1], [-18, -15], [18, -15], [26, -1], [18, 6], [-17, 6]]);
  ctx.fillStyle = hexMix('#6f3136', '#a5574b', day); ctx.fill(); ctx.strokeStyle = '#221f2a'; ctx.lineWidth = 2; ctx.stroke();
  line(ctx, -19, -12, 21, -8, '#d17a64', 1.3);
  // Open lattice rails allow water to remain visible through the navigation buoy.
  path(ctx, [[-14, -15], [-6, -73], [5, -73], [15, -15]]); ctx.strokeStyle = '#8a3940'; ctx.lineWidth = 4; ctx.stroke();
  line(ctx, -12, -20, 11, -48, '#b0524c', 2.3); line(ctx, 12, -20, -9, -48, '#4d2831', 2.2);
  line(ctx, -8, -47, 5, -70, '#be6256', 2); line(ctx, 9, -47, -5, -70, '#5d2c34', 2);
  line(ctx, -16, -18, 15, -18, '#cc7160', 1.2); line(ctx, -8, -47, 9, -47, '#aa584e', 1.2);
  path(ctx, [[-10, -74], [-13, -81], [13, -81], [10, -74]]); ctx.fillStyle = '#5f3339'; ctx.fill(); ctx.strokeStyle = '#242832'; ctx.lineWidth = 1.3; ctx.stroke();
  line(ctx, 0, -81, 0, -96, '#74323a', 2.2);
  if (lit > .04) glow(ctx, 0, -58, 66, `rgba(93,230,239,${lit * .22})`);
  if (flash > .025) glow(ctx, 0, -96, 37, `rgba(255,159,94,${flash * .72})`);
  const buoyLamp = flash > .2 ? `rgba(255,230,169,${.6 + flash * .4})` : lit > .15 ? `rgba(193,255,239,${.52 + lit * .4})` : '#c85446';
  circle(ctx, 0, -96, 5.2, buoyLamp, '#482a32', 1.2);
  circle(ctx, -1.2, -97.3, 1.4, `rgba(255,242,198,${.35 + Math.max(flash, lit) * .65})`);
  if (lit > .12) {
    line(ctx, -14, -17, -6, -72, `rgba(170,247,239,${lit})`, 2.2);
    line(ctx, -23, -2, 18, 3, `rgba(185,247,232,${lit * .75})`, 1.5);
  }
  ctx.restore();
}

"""Shared exact B-rep construction helpers; all linear dimensions are mm."""
import math
import cadquery as cq


def cylinder_x(x0, length, radius, y=0.0, z=0.0):
    return cq.Solid.makeCylinder(radius, length, cq.Vector(x0, y, z), cq.Vector(1, 0, 0))


def cylinder_z(x, y, z0, length, radius):
    return cq.Solid.makeCylinder(radius, length, cq.Vector(x, y, z0), cq.Vector(0, 0, 1))


def box_at(x0, y0, z0, dx, dy, dz, fillet_axis=None, fillet=0.0):
    result = cq.Workplane("XY").box(dx, dy, dz).translate((x0 + dx / 2, y0 + dy / 2, z0 + dz / 2))
    if fillet_axis and fillet:
        result = result.edges(fillet_axis).fillet(fillet)
    return result.val()


def fuse(shapes):
    shapes = [s for s in shapes if s is not None]
    if not shapes:
        raise ValueError("fuse requires at least one shape")
    result = shapes[0]
    if len(shapes) > 1:
        result = result.fuse(*shapes[1:])
    return result.clean()


def compound(shapes):
    solids = []
    for shape in shapes:
        if isinstance(shape, cq.Workplane):
            shape = shape.val()
        found = shape.Solids()
        solids.extend(found if found else [shape])
    return cq.Compound.makeCompound(solids)


def gear_points(root_radius, tip_radius, teeth, phase=0.0):
    """Periodic five-point-per-tooth trapezoidal gear outline in the YZ plane."""
    points = []
    pitch = 2 * math.pi / int(teeth)
    for i in range(int(teeth)):
        center = phase + i * pitch
        for fraction, radius in ((-0.50, root_radius), (-0.31, root_radius),
                                 (-0.19, tip_radius), (0.19, tip_radius),
                                 (0.31, root_radius)):
            a = center + fraction * pitch
            points.append((radius * math.cos(a), radius * math.sin(a)))
    return points


def gear_x(x0, length, root_radius, tip_radius, teeth, y=0.0, z=0.0,
           bore=0.0, phase=0.0):
    wp = cq.Workplane("YZ", origin=(x0, y, z)).polyline(
        gear_points(root_radius, tip_radius, teeth, phase)
    ).close().extrude(length)
    result = wp.val()
    if bore:
        result = result.cut(cylinder_x(x0 - 0.2, length + 0.4, bore, y, z)).clean()
    return result


def sector_x(x0, length, radius, center_deg, span_deg, z=78.0):
    """Genuine radial through-window cutter, drafted on YZ and extruded along X."""
    points = [(0.0, 0.0)]
    steps = 30
    for i in range(steps + 1):
        a = math.radians(center_deg - span_deg / 2 + span_deg * i / steps)
        points.append((radius * math.cos(a), radius * math.sin(a)))
    return cq.Workplane("YZ", origin=(x0, 0, z)).polyline(points).close().extrude(length).val()


def chamfer_circular(shape, amount=0.6):
    return cq.Workplane(obj=shape).edges("%CIRCLE").chamfer(amount).val()


def socket_bolt_z(x, y, head_bottom, shaft_bottom, shaft_radius=2.4,
                  head_radius=4.6, head_height=4.0):
    shaft_top = head_bottom + 0.35
    shaft = cylinder_z(x, y, shaft_bottom, shaft_top - shaft_bottom, shaft_radius)
    head = chamfer_circular(cylinder_z(x, y, head_bottom, head_height, head_radius), 0.32)
    bolt = fuse([shaft, head])
    socket = cq.Workplane("XY", origin=(x, y, head_bottom + head_height - 1.8)).polygon(6, 4.4).extrude(2.0).val()
    return bolt.cut(socket).clean()


def socket_bolt_x(face, y, z, shaft_depth, shaft_radius=2.4,
                  head_radius=4.6, head_height=4.5, negative=False):
    if negative:
        head_x = face - head_height
        head = chamfer_circular(cylinder_x(head_x, head_height, head_radius, y, z), 0.32)
        shaft = cylinder_x(face - 0.35, shaft_depth + 0.35, shaft_radius, y, z)
        bolt = fuse([shaft, head])
        socket = cq.Workplane("YZ", origin=(head_x - 0.2, y, z)).polygon(6, 4.4).extrude(2.2).val()
    else:
        head = chamfer_circular(cylinder_x(face, head_height, head_radius, y, z), 0.32)
        shaft = cylinder_x(face - shaft_depth, shaft_depth + 0.35, shaft_radius, y, z)
        bolt = fuse([shaft, head])
        socket = cq.Workplane("YZ", origin=(face + head_height - 1.8, y, z)).polygon(6, 4.4).extrude(2.0).val()
    return bolt.cut(socket).clean()


def washer_x(x0, thickness, inner_radius, outer_radius, y, z):
    return cylinder_x(x0, thickness, outer_radius, y, z).cut(
        cylinder_x(x0 - 0.1, thickness + 0.2, inner_radius, y
        , z)
    ).clean()

"""Continuous dark-steel vertical stem with a machined upper drive flat."""
import cadquery as cq


def build(params):
    p = params
    stem = cq.Solid.makeCylinder(
        0.5 * p["stem_diameter_mm"], 243.0,
        cq.Vector(0, 0, -64.0), cq.Vector(0, 0, 1),
    )
    # Two shallow flats identify the driven end without changing the 12 mm journal.
    for x0 in (5.0, -7.0):
        flat_cut = cq.Solid.makeBox(2.0, 14.0, 14.0, cq.Vector(x0, -7.0, 165.0))
        stem = stem.cut(flat_cut)
    return stem.clean()

