import { buildScene, SCENE } from './geometry.js';
import { sceneAt, normalizeTime, speedMultiplier, DURATION, clamp } from './motion.js';
import { Telemetry } from './telemetry.js';
import { SceneRenderer } from './renderer.js';
import { bindControls } from './controls.js';

const svg = document.getElementById('stage');
svg.innerHTML = buildScene();
const telemetry = new Telemetry(document);
const renderer = new SceneRenderer(svg, telemetry);

let state = { t: 0, speed: 60, playing: false, overlay: false };
let frameHandle = 0;
let anchorPhase = 0;
let anchorTime = 0;

function paint() {
  const complete = renderer.render(state);
  // Preserve control flags while replacing every derived tool / telemetry value.
  state = { ...complete, t: state.t, speed: state.speed, playing: state.playing, overlay: state.overlay };
  return state;
}

function stopFrame() {
  if (frameHandle) cancelAnimationFrame(frameHandle);
  frameHandle = 0;
}

function frame(now) {
  if (!state.playing) return;
  const elapsed = Math.max(0, (now - anchorTime) / 1000);
  const phase = normalizeTime(anchorPhase + elapsed * speedMultiplier(state.speed));
  state.t = phase;
  paint();
  frameHandle = requestAnimationFrame(frame);
}

function play() {
  if (state.playing && speedMultiplier(state.speed) > 0) return;
  stopFrame();
  state.playing = true;
  anchorPhase = state.t;
  anchorTime = performance.now();
  paint();
  if (speedMultiplier(state.speed) > 0) frameHandle = requestAnimationFrame(frame);
}

function pause() {
  if (state.playing && frameHandle) {
    // Account for the fraction of a frame since the previous paint, then hold exactly.
    state.t = normalizeTime(anchorPhase + Math.max(0, performance.now() - anchorTime) / 1000 * speedMultiplier(state.speed));
  }
  state.playing = false;
  stopFrame();
  paint();
}

/** Deterministic absolute seek: cancels wall-clock transport and rebuilds the pose. */
function renderAt(seconds) {
  state.playing = false;
  stopFrame();
  state.t = normalizeTime(Number(seconds));
  paint();
  return snapshot();
}

function setSpeed(value) {
  const next = clamp(Number(value) || 0, 0, 100);
  if (state.playing) {
    const now = performance.now();
    const elapsed = Math.max(0, (now - anchorTime) / 1000);
    anchorPhase = normalizeTime(anchorPhase + elapsed * speedMultiplier(state.speed));
    anchorTime = now;
    state.t = anchorPhase;
  }
  const wasPlaying = state.playing;
  state.speed = next;
  paint();
  if (wasPlaying) {
    stopFrame();
    if (speedMultiplier(next) > 0) frameHandle = requestAnimationFrame(frame);
    else state.playing = true; // speed 0 is a deliberate cadence hold
  }
  return snapshot();
}

function togglePivot(force) {
  state.overlay = typeof force === 'boolean' ? force : !state.overlay;
  paint(); // no changes to t or any canonical geometric parameter
  return snapshot();
}

function reset() {
  stopFrame();
  state = { t: 0, speed: 60, playing: false, overlay: false };
  paint();
  return snapshot();
}

function snapshot() {
  const base = sceneAt(state.t, state.speed);
  return JSON.parse(JSON.stringify({
    ...base,
    playing: state.playing,
    overlay: state.overlay,
    speed: state.speed,
    tools: {
      compass: base.compass,
      tsquare: base.tsquare,
      cutter: base.cutter,
      ribbon: base.ribbon,
      arcProgress: base.progress.arc,
      trimProgress: base.progress.trim,
    },
    controls: {
      play: state.playing,
      pause: !state.playing,
      scrub: Number(document.getElementById('scrub').value),
      speed: state.speed,
      speedReadout: document.getElementById('speed-readout').textContent,
      pivot: state.overlay,
      scrubFill: document.getElementById('scrub').style.getPropertyValue('--fill'),
      speedFill: document.getElementById('speed-slider').style.getPropertyValue('--fill'),
    },
  }));
}

bindControls({ play, pause, reset, seek: renderAt, setSpeed, togglePivot, getState: snapshot });
window.renderAt = renderAt;
window.__getSceneState = snapshot;
window.__SCENE_EXPORT__ = Object.freeze({ duration: DURATION, width: SCENE.width, height: SCENE.height, fps: 30 });
paint();
window.__SCENE_READY__ = true;

/** Pure deterministic mechanism model. No wall-clock or accumulated state. */
import {
  NEEDLE, COMPASS_LENGTH, COMPASS_SPREAD, COMPASS_SWEEP,
  COMPASS_BASE_ANGLE, TSQUARE_TRAVEL,
} from './geometry.js';

export const DURATION = 6;
export const clamp = (v, min = 0, max = 1) => Math.max(min, Math.min(max, v));
export const lerp = (a, b, u) => a + (b - a) * u;
export const smooth = u => { const x = clamp(u); return x * x * (3 - 2 * x); };
export const smoother = u => { const x = clamp(u); return x * x * x * (x * (x * 6 - 15) + 10); };

export function normalizeTime(seconds) {
  const value = Number.isFinite(Number(seconds)) ? Number(seconds) : 0;
  if (Math.abs(value - DURATION) < 1e-9) return 0;
  if (value >= 0 && value < DURATION) return value;
  return ((value % DURATION) + DURATION) % DURATION;
}

function resetValue(t, start = 4.8) {
  return t < start ? 1 : 1 - smoother((t - start) / (DURATION - start));
}

function phaseInfo(t) {
  if (t < 1.8) return { index: 0, name: 'SCRIBE CONSTRUCTION', code: '01', local: t / 1.8 };
  if (t < 2.8) return { index: 1, name: 'INDEX T-SQUARE', code: '02', local: (t - 1.8) / 1.0 };
  if (t < 4.8) return { index: 2, name: 'GUIDED TRIM & CURL', code: '03', local: (t - 2.8) / 2.0 };
  return { index: 3, name: 'RETURN TO REGISTER', code: '04', local: (t - 4.8) / 1.2 };
}

/** Shared speed law: changing cadence changes rate, never canonical poses. */
export function speedMultiplier(speed) {
  const s = clamp(Number(speed) || 0, 0, 100);
  return s / 60; // 60 => canonical 1.0 cadence; zero holds transport phase
}

function cutterRate(t) {
  // Derivative of the same smooth envelope used by the tool, in mm/s.
  if (t >= 2.8 && t < 4.8) {
    const u = (t - 2.8) / 2;
    return (40 / 2) * (30 * u * u * (1 - u) * (1 - u));
  }
  if (t >= 4.8) {
    const u = (t - 4.8) / 1.2;
    return (40 / 1.2) * (30 * u * u * (1 - u) * (1 - u));
  }
  return 0;
}

export function sceneAt(seconds, speed = 60) {
  const t = normalizeTime(seconds);
  const phase = phaseInfo(t);
  const returning = resetValue(t);
  const arcProgress = t < 1.8 ? smoother(t / 1.8) : returning;
  const squareProgress = t < 1.8 ? 0 : t < 2.8 ? smoother((t - 1.8) / 1.0) : returning;
  const trimProgress = t < 2.8 ? 0 : t < 4.8 ? smoother((t - 2.8) / 2.0) : returning;
  const bladeProgress = t < 2.8 ? 0 : t < 4.8 ? smooth((t - 2.8) / 0.72) : returning;
  const ribbonProgress = trimProgress;

  const compassDegrees = COMPASS_BASE_ANGLE + COMPASS_SWEEP * arcProgress;
  const compassRadians = compassDegrees * Math.PI / 180;
  const spreadRadians = COMPASS_SPREAD * Math.PI / 180;
  // A vertex of two equal rigid legs: chord R = 2 L sin(spread/2).
  // Here R = L = 200, so spread = 60 degrees.
  const localHinge = { x: 100, y: -Math.sqrt(COMPASS_LENGTH ** 2 - 100 ** 2) };
  const rotate = point => ({
    x: NEEDLE.x + point.x * Math.cos(compassRadians) - point.y * Math.sin(compassRadians),
    y: NEEDLE.y + point.x * Math.sin(compassRadians) + point.y * Math.cos(compassRadians),
  });
  const hinge = rotate(localHinge);
  const pencil = {
    x: NEEDLE.x + COMPASS_LENGTH * Math.cos(compassRadians),
    y: NEEDLE.y + COMPASS_LENGTH * Math.sin(compassRadians),
  };
  const swingDegrees = compassDegrees - COMPASS_BASE_ANGLE;
  const cutterDistance = 40 * trimProgress;
  const bladeExtension = 24 * bladeProgress;
  const rate = cutterRate(t);
  const speedGain = speedMultiplier(speed);

  const telemetry = {
    arcAngle: COMPASS_SWEEP * arcProgress,
    compassTravel: COMPASS_LENGTH * COMPASS_SWEEP * Math.PI / 180 * arcProgress,
    tsquarePosition: TSQUARE_TRAVEL * squareProgress,
    cutterSpeed: rate * speedGain,
    trimProgress: trimProgress * 100,
  };

  return {
    t,
    duration: DURATION,
    phase: t,
    phaseIndex: phase.index,
    phaseName: phase.name,
    phaseCode: phase.code,
    phaseLocal: phase.local,
    speed: clamp(Number(speed) || 0, 0, 100),
    playing: false,
    overlay: false,
    progress: { arc: arcProgress, square: squareProgress, trim: trimProgress, ribbon: ribbonProgress, blade: bladeProgress, reset: 1 - returning },
    compass: { degrees: compassDegrees, swingDegrees, spreadDegrees: COMPASS_SPREAD, radius: COMPASS_LENGTH, needle: { ...NEEDLE }, hinge, pencil },
    tsquare: { x: -TSQUARE_TRAVEL * squareProgress, renderX: -60 - TSQUARE_TRAVEL * squareProgress, position: TSQUARE_TRAVEL * squareProgress, y: 0, angle: 90 },
    cutter: { distance: cutterDistance, bladeExtension, thumbOffset: bladeExtension, angle: 55, baseX: 880, baseY: 320 },
    ribbon: { progress: ribbonProgress },
    telemetry,
  };
}

export const phaseForScrub = value => clamp(Number(value) || 0, 0, DURATION);

/** SVG renderer: maps a complete pure state to a complete pose, with no deltas. */
import { sceneAt } from './motion.js';

const fmt = n => Number(n.toFixed(4));
const attr = (el, name, value) => el.setAttribute(name, String(value));

export class SceneRenderer {
  constructor(svg, telemetry) {
    this.svg = svg;
    this.telemetry = telemetry;
    const ids = [
      'compass-tool', 'tsquare-tool', 'golden-arc', 'cutter-tool', 'segmented-blade',
      'thumb-lock', 'trim-line', 'paper-ribbon', 'ribbon-body', 'ribbon-highlight',
      'ribbon-shadow', 'ribbon-outline', 'phase-label', 'phase-readout', 'phase-dot',
      'speed-readout', 'speed-slider', 'scrub', 'pivot-overlay', 'pivot-toggle',
      'pivot-toggle-text', 'pivot-card', 'overlay-needle-axis', 'overlay-pencil-axis',
      'overlay-hinge-ring', 'overlay-hinge-cross', 'construction-radius',
      'tsquare-guide-vector', 'tsquare-guide-arrow', 'cutter-blade-axis',
      'overlay-hinge-label', 'overlay-radius-label', 'overlay-guide-label',
      'overlay-blade-label', 'play', 'pause',
    ];
    this.el = Object.fromEntries(ids.map(id => [id, document.getElementById(id)]));
    this.sensitive = document.querySelectorAll('.overlay-sensitive');
  }

  render(inputState) {
    const state = {
      ...sceneAt(inputState.t, inputState.speed),
      playing: Boolean(inputState.playing),
      overlay: Boolean(inputState.overlay),
    };
    const e = this.el;
    const c = state.compass;
    const cut = state.cutter;

    // A single transform rotates hinge, both legs, wheel and pencil about the needle.
    attr(e['compass-tool'], 'transform', `translate(${c.needle.x} ${c.needle.y}) rotate(${fmt(c.swingDegrees)})`);
    attr(e['golden-arc'], 'stroke-dashoffset', fmt(100 * (1 - state.progress.arc)));
    attr(e['tsquare-tool'], 'transform', `translate(${fmt(state.tsquare.renderX)} 0)`);

    const radians = cut.angle * Math.PI / 180;
    const cutterX = cut.baseX + Math.cos(radians) * cut.distance;
    const cutterY = cut.baseY + Math.sin(radians) * cut.distance;
    attr(e['cutter-tool'], 'transform', `translate(${fmt(cutterX)} ${fmt(cutterY)}) rotate(${cut.angle})`);
    attr(e['segmented-blade'], 'transform', `translate(${fmt(cut.bladeExtension)} 0)`);
    attr(e['thumb-lock'], 'transform', `translate(${fmt(116 + cut.thumbOffset)} -12)`);

    const trimStart = { x: cut.baseX + Math.cos(radians) * 159, y: cut.baseY + Math.sin(radians) * 159 };
    const trimEnd = { x: trimStart.x + Math.cos(radians) * cut.distance, y: trimStart.y + Math.sin(radians) * cut.distance };
    attr(e['trim-line'], 'd', `M${fmt(trimStart.x)} ${fmt(trimStart.y)}L${fmt(trimEnd.x)} ${fmt(trimEnd.y)}`);
    attr(e['trim-line'], 'stroke-dashoffset', fmt(100 * (1 - state.progress.trim)));

    // The curl's origin follows the cutter and its visible length follows trim progress.
    const ribbonD = `M${fmt(trimEnd.x)} ${fmt(trimEnd.y)}C${fmt(trimEnd.x - 9)} ${fmt(trimEnd.y + 25)} ${fmt(trimEnd.x - 55)} ${fmt(trimEnd.y + 10)} ${fmt(trimEnd.x - 65)} ${fmt(trimEnd.y + 45)}C${fmt(trimEnd.x - 79)} ${fmt(trimEnd.y + 78)} ${fmt(trimEnd.x - 35)} ${fmt(trimEnd.y + 88)} ${fmt(trimEnd.x - 32)} ${fmt(trimEnd.y + 58)}C${fmt(trimEnd.x - 29)} ${fmt(trimEnd.y + 37)} ${fmt(trimEnd.x - 60)} ${fmt(trimEnd.y + 34)} ${fmt(trimEnd.x - 60)} ${fmt(trimEnd.y + 55)}C${fmt(trimEnd.x - 60)} ${fmt(trimEnd.y + 67)} ${fmt(trimEnd.x - 45)} ${fmt(trimEnd.y + 70)} ${fmt(trimEnd.x - 40)} ${fmt(trimEnd.y + 59)}`;
    for (const id of ['ribbon-body', 'ribbon-highlight', 'ribbon-shadow', 'ribbon-outline']) {
      attr(e[id], 'd', ribbonD);
      attr(e[id], 'stroke-dashoffset', fmt(100 * (1 - state.progress.ribbon)));
    }

    const ribbonVisibility = state.progress.ribbon > 0.00001 ? 1 : 0;
    attr(e['paper-ribbon'], 'opacity', ribbonVisibility);
    attr(e['paper-ribbon'], 'visibility', ribbonVisibility ? 'visible' : 'hidden');

    e['phase-label'].textContent = `${state.phaseCode}  /  ${state.phaseName}`;
    e['phase-readout'].textContent = `${state.t.toFixed(2)} s`;
    e['phase-dot'].setAttribute('class', `phase-dot phase-${state.phaseIndex}`);
    this.telemetry.render(state);
    this.renderControls(state);
    this.renderOverlay(state);
    return state;
  }

  renderControls(state) {
