/** Five display channels. Each is a pure projection of the shared scene state. */
const METRICS = [
  { key: 'arcAngle', max: 58, code: 'ARC', format: v => `${v.toFixed(1)}°` },
  { key: 'compassTravel', max: 202.4, code: 'PTH', format: v => `${v.toFixed(1)} mm` },
  { key: 'tsquarePosition', max: 64, code: 'IDX', format: v => `${v.toFixed(1)} mm` },
  { key: 'cutterSpeed', max: 150, code: 'VEL', format: v => `${v.toFixed(1)}` },
  { key: 'trimProgress', max: 100, code: 'CUT', format: v => `${v.toFixed(0)}%` },
];

export class Telemetry {
  constructor(root = document) {
    this.nodes = METRICS.map((metric, index) => ({
      metric,
      value: root.getElementById(`gauge-value-${index}`),
      arc: root.getElementById(`gauge-arc-${index}`),
      needle: root.getElementById(`gauge-needle-${index}`),
      meter: root.getElementById(`meter-${index}`),
      code: root.getElementById(`gauge-code-${index}`),
    }));
  }

  render(state) {
    this.nodes.forEach(({ metric, value, arc, needle, meter, code }) => {
      const raw = Math.max(0, state.telemetry[metric.key]);
      const fraction = Math.max(0, Math.min(1, raw / metric.max));
      value.textContent = metric.format(raw);
      arc.setAttribute('stroke-dashoffset', (100 * (1 - fraction)).toFixed(4));
      needle.setAttribute('transform', `rotate(${-120 + 240 * fraction})`);
      meter.setAttribute('width', (133 * fraction).toFixed(4));
      code.textContent = `${metric.code} ${String(Math.round(fraction * 99)).padStart(2, '0')}`;
    });
  }
}

"""Small orthogonal-plane and B-rep helpers shared by the part builders."""
import math
import cadquery as cq


def rounded_prism(plane, width, height, radius, depth, center=(0.0, 0.0)):
    """Rounded 2-D profile extruded normal to an explicit sketch plane."""
    wp = cq.Workplane(plane).center(center[0], center[1])
    if radius > 0.0:
        return (wp.sketch().rect(width, height).vertices().fillet(radius)
                .finalize().extrude(depth).val())
    return wp.rect(width, height).extrude(depth).val()


def box_at(x0, y0, z0, dx, dy, dz):
    return cq.Solid.makeBox(dx, dy, dz, cq.Vector(x0, y0, z0))


def cylinder(radius, length, point, direction):
    return cq.Solid.makeCylinder(radius, length, cq.Vector(*point), cq.Vector(*direction))


def cylinder_x(radius, length, x0, y, z):
    """Circle sketched on a YZ auxiliary plane, then extruded along +X."""
    yz = cq.Plane(origin=cq.Vector(x0, 0, 0), xDir=cq.Vector(0, 1, 0),
                  normal=cq.Vector(1, 0, 0))
    return cq.Workplane(yz).center(y, z).circle(radius).extrude(length).val()


def cylinder_between(radius, start, end):
    delta = cq.Vector(end[0]-start[0], end[1]-start[1], end[2]-start[2])
    return cq.Solid.makeCylinder(radius, delta.Length, cq.Vector(*start), delta.normalized())


def fuse_all(base, additions):
    items = [s for s in additions if s is not None]
    return base.fuse(*items) if items else base


def compounded(shapes):
    return cq.Compound.makeCompound(shapes)


def front_frame(p):
    """Return plane, origin, in-plane up vector and outward normal.

    Local sketch axes are X and the slope-up direction.  Therefore a positive
    local Y rectangle coordinate is exactly along the tilted bezel; a negative
    extrusion goes into the instrument.  This avoids accidental ZX mapping.
    """
    angle = math.radians(p["front_tilt_deg"])
    origin = cq.Vector(0.0, 0.0, p["front_bottom_z_mm"])
    up = cq.Vector(0.0, math.sin(angle), math.cos(angle))
    normal = cq.Vector(0.0, -math.cos(angle), math.sin(angle))
    plane = cq.Plane(origin=origin, xDir=cq.Vector(1, 0, 0), normal=normal)
    slope_length = ((p["front_top_z_mm"] - p["front_bottom_z_mm"]) / math.cos(angle))
    return plane, origin, up, normal, slope_length


def front_point(origin, up, normal, x, v, d=0.0):
    return (origin.x + x + normal.x*d + up.x*v,
            origin.y + normal.y*d + up.y*v,
            origin.z + normal.z*d + up.z*v)


def front_prism(p, x, v, width, height, depth, d=0.0, radius=0.0):
    plane, origin, up, normal, _ = front_frame(p)
    pos = front_point(origin, up, normal, x, v, d)
    local_plane = cq.Plane(origin=pos, xDir=cq.Vector(1, 0, 0), normal=normal)
    return rounded_prism(local_plane, width, height, radius, depth)


def front_y_at_global_z(p, z, rear_offset=True, seam=0.0):
    """Y of the back edge of the tilted bezel at a given world Z."""
    a = math.radians(p["front_tilt_deg"])
    thickness = p["front_thickness_mm"] / math.cos(a) if rear_offset else 0.0
    return (z-p["front_bottom_z_mm"])*math.tan(a) + thickness + seam

"""Small analytic B-rep construction helpers shared by the six builders."""
import math
import cadquery as cq


def y_cylinder(x, z, radius, y0, y1):
    return cq.Workplane(obj=cq.Solid.makeCylinder(
        radius, y1 - y0, cq.Vector(x, y0, z), cq.Vector(0, 1, 0)))


def z_cylinder(x, y, radius, z0, z1):
    return cq.Workplane(obj=cq.Solid.makeCylinder(
        radius, z1 - z0, cq.Vector(x, y, z0), cq.Vector(0, 0, 1)))


def xz_prism(points, y_center, thickness):
    return (cq.Workplane("XZ").polyline(points).close()
            .extrude(thickness * 0.5, both=True)
            .translate((0, y_center, 0)))


def xz_link(p0, p1, width, y_center, thickness):
    """A flat, square-ended diagonal strap in XZ, extruded symmetrically."""
    dx = p1[0] - p0[0]
    dz = p1[1] - p0[1]
    length = math.hypot(dx, dz)
    nx = -dz / length * width * 0.5
    nz = dx / length * width * 0.5
    points = [
        (p0[0] + nx, p0[1] + nz),
        (p1[0] + nx, p1[1] + nz),
        (p1[0] - nx, p1[1] - nz),
        (p0[0] - nx, p0[1] - nz),
    ]
    return xz_prism(points, y_center, thickness)


def xz_capsule(p0, p1, radius, width, y_center, thickness):
    """Round-ended strap; circles give exact analytic heads and root arcs."""
    result = xz_link(p0, p1, width, y_center, thickness)
    result = result.union(y_cylinder(p0[0], p0[1], radius,
                                    y_center - thickness * 0.5,
                                    y_center + thickness * 0.5))
    result = result.union(y_cylinder(p1[0], p1[1], radius,
                                    y_center - thickness * 0.5,
                                    y_center + thickness * 0.5))
    return result


def fuse_all(objects):
    result = objects[0]
    for item in objects[1:]:
        result = result.union(item)
    return result.clean()


def annulus_z(x, y, outer_radius, inner_radius, z0, z1):
    outer = z_cylinder(x, y, outer_radius, z0, z1)
    inner = z_cylinder(x, y, inner_radius, z0 - 0.2, z1 + 0.2)
    return outer.cut(inner)


def yz_cylinder_at_x(x0, x1, y, z, radius):
    return cq.Workplane(obj=cq.Solid.makeCylinder(
        radius, x1 - x0, cq.Vector(x0, y, z), cq.Vector(1, 0, 0)))

