  updateBlades(radius) {
    const angleOffset = .27 + (51 - radius) * .0035;
    const step = Math.PI * 2 / 9;
    for (let index = 0; index < 9; index++) {
      const angle = index * step;
      const pivot = polar(61, angle);
      const outer = polar(66, angle + .78);
      const innerNext = polar(radius, angle + angleOffset + step * .96);
      const inner = polar(radius, angle + angleOffset);
      const d = [
        `M ${pointString(pivot)}`,
        `Q ${pointString(polar(70, angle + .37))} ${pointString(outer)}`,
        `L ${pointString(innerNext)}`,
        `Q ${pointString(polar(radius * .91, angle + angleOffset + step * .47))} ${pointString(inner)}`,
        `Q ${pointString(polar(radius * 1.48, angle + .15))} ${pointString(pivot)} Z`,
      ].join(' ');
      this.blades[index].setAttribute('d', d);
    }
    this.irisOpening.setAttribute('r', fixed(radius));
  }

  render(view) {
    const {
      time, aperture, distance, finish, section, explodedOverride, focusInteractive,
    } = view;
    const explodeTimeline = phase(time, 0, 2);
    const exploded = explodedOverride === null ? explodeTimeline : explodedOverride ? 1 : 0;
    const irisPhase = phase(time, 2, 4);
    const focusPhase = phase(time, 4, 6);
    const exposurePhase = phase(time, 6, 8);
    const frontOpen = phase(time, 6.05, 7.03);
    const rearClose = phase(time, 7.05, 7.94);
    const exposed = phase(time, 6.42, 7.69);
    const irisPulse = Math.sin(irisPhase * Math.PI);
    const finishDefinition = FINISHES[finish] || FINISHES.silver;

    // Body finish is a real material swap, shared by all exterior metal parts.
    const metalStops = [finishDefinition.metalLight, finishDefinition.metalMid, finishDefinition.metalMid, finishDefinition.metalDark];
    metalStops.forEach((color, index) => $(this.root, `metal-stop-${index}`).setAttribute('stop-color', color));
    this.body.querySelectorAll('path').forEach(path => {
      if (path.getAttribute('fill') === 'url(#leather-pattern)') path.setAttribute('stroke', finishDefinition.edge);
    });
    this.frontKnurl.setAttribute('opacity', finish === 'black' ? '.64' : '.86');

    const reveal = Math.max(.06, explodeTimeline, exploded, time >= 2 ? .97 : 0);
    this.mechanics.setAttribute('opacity', fixed(reveal * (section === 'right' ? 1 : .38)));
    this.sectionCover.setAttribute('opacity', fixed(lerp(.94, section === 'right' ? .12 : .72, reveal)));
    this.sectionHatch.setAttribute('opacity', fixed(lerp(.3, section === 'right' ? .07 : .22, reveal)));
    this.glass.setAttribute('opacity', fixed(lerp(.28, 1, Math.max(exploded, time >= 2 ? .95 : 0))));
    this.iris.setAttribute('opacity', section === 'left' ? '1' : '.88');
    this.barrelCutaway.setAttribute('opacity', fixed(lerp(.12, section === 'left' ? .96 : .55, reveal)));
    this.lensShadow.setAttribute('opacity', fixed(exploded * .13));

    // Barrel sections and seven elements share x-axis travel; no nested clocks.
    this.barrelFront.setAttribute('transform', `translate(${fixed(-32 * exploded)} 0)`);
    this.barrelRear.setAttribute('transform', `translate(${fixed(-10 * exploded)} 0)`);
    const travel = focusTravel(distance);
    const demoTravel = (1 - focusPhase) * (Number.isFinite(distance) ? lerp(14, 0, clamp((distance - .7) / 9.3, 0, 1)) : 0);
    const explodedPositions = [100, 157, 211, 263, 314, 359, 398];
    const compactPositions = [337, 350, 363, 376, 389, 402, 415];
    this.lenses.forEach((lens, index) => {
      const floating = index >= 4 ? travel * (index === 4 ? .65 : 1) + demoTravel * (index === 4 ? .55 : 1) : 0;
      const x = lerp(compactPositions[index], explodedPositions[index], exploded) + floating;
      const sectionLift = section === 'left' && index < 3 ? 0 : 0;
      lens.setAttribute('transform', `translate(${fixed(x)} ${AXIS_Y + sectionLift})`);
      lens.setAttribute('opacity', fixed(index < 4 ? lerp(.5, 1, exploded) : 1));
    });

    const baseRadius = apertureRadius(aperture);
    const visualRadius = baseRadius + (52 - baseRadius) * irisPulse * .8;
    this.updateBlades(visualRadius);
    this.iris.setAttribute('transform', `translate(428 ${AXIS_Y}) scale(.66 1)`);

    // Rangefinder double images. During the built-in focusing demonstration the
    // near images resolve; infinity is always exactly coincident. A manual
    // focusing interaction exposes the physical near-focus disparity again.
    const nearError = Number.isFinite(distance) ? 12 * Math.exp(-(distance - .7) * .37) : 0;
    const demoResolution = focusInteractive ? 1 : 1 - focusPhase;
    const disparity = nearError * demoResolution;
    this.windowPairs.forEach(({ a, b, amber }, index) => {
      const sign = index < 2 ? 1 : -1;
      a.setAttribute('transform', `translate(${fixed(-disparity * .45 * sign)} 0)`);
      b.setAttribute('transform', `translate(${fixed(disparity * .45 * sign)} 0)`);
      b.setAttribute('opacity', fixed(disparity < .03 ? 0 : (amber ? .55 : .43)));
    });

    // The front curtain opens, the sensor integrates, then the rear curtain closes.
    // To keep the terminal state a readable full-exposure cutaway, the sensor's
    // recorded spectrum remains visible behind the closed rear curtain.
    this.frontCurtain.setAttribute('transform', `translate(0 ${fixed(-119 * frontOpen)})`);
    this.rearCurtain.setAttribute('transform', `translate(18 ${fixed(119 * (1 - rearClose))})`);
    this.sensorLight.setAttribute('opacity', fixed(exposed * .94));
    this.sensorScan.setAttribute('opacity', fixed(exposurePhase > 0 && exposurePhase < 1 ? .75 : 0));
    this.sensorScan.setAttribute('transform', `translate(0 ${fixed(100 * exposurePhase)})`);
    this.gears.forEach((gear, index) => {
      const direction = index === 1 ? -1 : 1;
      const rotation = direction * (frontOpen * 155 + rearClose * 128 + focusPhase * 35);
      gear.setAttribute('transform', `translate(${gear.dataset.x} ${gear.dataset.y}) rotate(${fixed(rotation)})`);
    });

    // Iris diameter, ray cone, exposure and wavefront all use the same radius.
    const rayHalf = visualRadius * .92;
    const frontX = lerp(326, 82, exploded);
    this.mainCone.setAttribute('d', `M ${fixed(frontX)} ${fixed(AXIS_Y - rayHalf * .45)} L 428 ${fixed(AXIS_Y - rayHalf)} L 657 273 L 657 372 L 428 ${fixed(AXIS_Y + rayHalf)} L ${fixed(frontX)} ${fixed(AXIS_Y + rayHalf * .45)} Z`);
    this.mainCone.setAttribute('opacity', fixed(lerp(.08, .62, exposed) + exploded * .07));
    this.apertureRayTop.setAttribute('d', `M ${fixed(frontX)} ${AXIS_Y} L 428 ${fixed(AXIS_Y - rayHalf)} L657 272`);
    this.apertureRayBottom.setAttribute('d', `M ${fixed(frontX)} ${AXIS_Y} L 428 ${fixed(AXIS_Y + rayHalf)} L657 372`);
    this.apertureRayTop.setAttribute('opacity', fixed(.15 + exposed * .62));
    this.apertureRayBottom.setAttribute('opacity', fixed(.15 + exposed * .62));
    const waveX = lerp(431, 657, exposurePhase);
    this.photon.setAttribute('transform', `translate(${fixed(waveX)} 0)`);
    this.photon.setAttribute('opacity', fixed(time >= 6 && time < 7.8 ? Math.sin(exposurePhase * Math.PI) * .9 : 0));
    this.rfCones.setAttribute('opacity', fixed(.52 + exposed * .48));

    this.sectionFrame.setAttribute('d', section === 'right'
      ? 'M523 224 L704 243 L709 417 L530 397 Z'
      : 'M275 235 Q355 212 448 245 L455 402 Q355 424 270 400 Z');
    this.sectionFrame.setAttribute('opacity', fixed(.28 + reveal * .42));

    return {
      explodedAmount: exploded,
      visualApertureRadius: visualRadius,
      frontCurtainOpen: frontOpen,
      rearCurtainClosed: rearClose,
      sensorExposure: exposed,
      focusDisparity: disparity,
    };
  }
}

import {
  F_STOPS, distanceToNormalized, formatDistance, normalizedToDistance,
  stepAperture, stepFocus,
} from './optics.js';

const byId = id => document.getElementById(id);

function fillRange(input) {
  const min = Number(input.min || 0);
  const max = Number(input.max || 100);
  const percentage = ((Number(input.value) - min) / (max - min)) * 100;
  input.style.setProperty('--fill', `${Math.max(0, Math.min(100, percentage))}%`);
}

/** Wires accessible HTML controls to the single scene store. */
export function createControls(actions) {
  const elements = {
    play: byId('play'), pause: byId('pause'), scrub: byId('scrub'),
    aperture: byId('aperture-slider'), focus: byId('focus-slider'),
    finish: byId('finish-select'), sectionInset: byId('section-inset'),
  };

  elements.play.addEventListener('click', actions.play);
  elements.pause.addEventListener('click', actions.pause);
  const scrub = () => actions.setTime(Number(elements.scrub.value), true);
  elements.scrub.addEventListener('input', scrub);
  elements.scrub.addEventListener('change', scrub);

  elements.aperture.addEventListener('input', () => {
    actions.setParameter('aperture', Number(elements.aperture.value));
  });
  byId('aperture-prev').addEventListener('click', () => {
    actions.setParameter('aperture', stepAperture(actions.getState().aperture, -1));
  });
  byId('aperture-next').addEventListener('click', () => {
    actions.setParameter('aperture', stepAperture(actions.getState().aperture, 1));
  });

  elements.focus.addEventListener('input', () => {
    actions.setParameter('distance', normalizedToDistance(elements.focus.value));
  });
  byId('focus-prev').addEventListener('click', () => {
    actions.setParameter('distance', stepFocus(actions.getState().distance, -1));
  });
  byId('focus-next').addEventListener('click', () => {
    actions.setParameter('distance', stepFocus(actions.getState().distance, 1));
  });

  elements.finish.addEventListener('change', () => actions.setParameter('finish', elements.finish.value));
  byId('exploded-toggle').addEventListener('click', () => {
    actions.setParameter('explodedOverride', !actions.getState().exploded);
  });
  byId('section-left').addEventListener('click', () => actions.setParameter('section', 'left'));
  byId('section-right').addEventListener('click', () => actions.setParameter('section', 'right'));
  byId('reset-btn').addEventListener('click', actions.reset);

  byId('tab-aperture').addEventListener('click', () => actions.setParameter('activeControl', 'aperture'));
  byId('tab-focus').addEventListener('click', () => actions.setParameter('activeControl', 'focus'));
  document.querySelectorAll('.chapter-nav [data-phase]').forEach(button => {
    const times = { lens: 0, aperture: 2, focus: 4, exposure: 6 };
    button.addEventListener('click', () => actions.setTime(times[button.dataset.phase], true));
  });

  const menu = byId('menu-btn');
  const index = byId('product-index');
  menu.addEventListener('click', () => {
    const expanded = menu.getAttribute('aria-expanded') === 'true';
    menu.setAttribute('aria-expanded', String(!expanded));
    index.hidden = expanded;
  });

  return {
    sync(state, visual, phaseName) {
      elements.scrub.value = state.time.toFixed(3);
      elements.aperture.value = String(state.aperture);
      elements.focus.value = String(distanceToNormalized(state.distance).toFixed(3));
      elements.finish.value = state.finish;
      [elements.scrub, elements.aperture, elements.focus].forEach(fillRange);

      byId('time-display').innerHTML = `${state.time.toFixed(1).padStart(4, '0')} <span>/ 08.0</span>`;
      byId('aperture-value').textContent = state.aperture.toFixed(1).replace('.0', '');
      elements.aperture.setAttribute('aria-valuetext', `f/${state.aperture.toFixed(1)}`);
      const focusText = formatDistance(state.distance);
      byId('focus-value').textContent = focusText;
      byId('focus-value').dataset.infinite = String(!Number.isFinite(state.distance));
      byId('focus-unit').textContent = Number.isFinite(state.distance) ? 'm' : 'infinity';
      elements.focus.setAttribute('aria-valuetext', Number.isFinite(state.distance) ? `${focusText} metres` : 'Infinity');

      byId('phase-name').textContent = phaseName;
      document.querySelectorAll('.chapter-nav [data-phase]').forEach(button => {
        const active = button.dataset.phase === state.phase;
        button.classList.toggle('active', active);
        if (active) button.setAttribute('aria-current', 'step');
        else button.removeAttribute('aria-current');
      });
      elements.play.classList.toggle('active', state.playing);
      elements.pause.classList.toggle('active', !state.playing && state.time > 0 && state.time < 8);
      elements.play.setAttribute('aria-pressed', String(state.playing));

      const apertureActive = state.activeControl === 'aperture';
      byId('tab-aperture').classList.toggle('active', apertureActive);
      byId('tab-focus').classList.toggle('active', !apertureActive);
      byId('tab-aperture').setAttribute('aria-pressed', String(apertureActive));
      byId('tab-focus').setAttribute('aria-pressed', String(!apertureActive));
      byId('aperture-readout').classList.toggle('active', apertureActive);
      byId('focus-readout').classList.toggle('active', !apertureActive);

      const right = state.section === 'right';
      byId('section-left').classList.toggle('active', !right);
      byId('section-right').classList.toggle('active', right);
      byId('section-left').setAttribute('aria-pressed', String(!right));
      byId('section-right').setAttribute('aria-pressed', String(right));
      elements.sectionInset.textContent = right ? 'SECTION R · FOCAL PLANE' : 'SECTION L · FLOATING OPTICS';

      const explodedButton = byId('exploded-toggle');
      explodedButton.setAttribute('aria-pressed', String(visual.explodedAmount >= .5));
      byId('mode-status').textContent = visual.explodedAmount >= .98 ? 'EXPLODED' : visual.explodedAmount <= .02 ? 'ASSEMBLED' : 'IN TRANSITION';
      byId('finish-swatch').dataset.finish = state.finish;

      byId('playback-status').textContent = state.playing
        ? 'PLAYING / ONE SHOT'
        : state.time >= 8 ? 'EXPOSURE COMPLETE' : state.time > 0 ? 'PAUSED / HOLD' : 'READY / ONE SHOT';
      document.querySelector('.status-dot').classList.toggle('playing', state.playing);

      const captions = state.time < 2 ? 'ASSEMBLED EXTERIOR / AXIAL RELEASE'
        : state.time < 4 ? 'NINE-BLADE IRIS / COORDINATED ACTUATION'
          : state.time < 6 ? 'FLOATING GROUP / RANGEFINDER COUPLING'
            : state.time < 8 ? 'FOCAL PLANE / EXPOSURE INTEGRATION'
              : 'FULL EXPOSURE / COMPLETE OPTICAL SECTION';
      byId('mechanism-caption').textContent = captions;
      const phaseLabels = {
        lens: 'LENS / AXIAL ASSEMBLY', aperture: 'APERTURE / NINE BLADES',
        focus: 'FOCUS / DOUBLE-IMAGE COUPLING', exposure: 'EXPOSURE / FOCAL PLANE',
      };
      byId('phase-name').textContent = phaseLabels[state.phase];
    },
  };
}

import { CameraStage } from './camera-stage.js';
import { createControls } from './controls.js';
import { clamp, DURATION, timelinePhase } from './optics.js';

const initialParameters = () => ({
  aperture: 2.5,
  distance: 0.7,
  finish: 'silver',
  section: 'right',
  explodedOverride: null,
  activeControl: 'aperture',
  focusInteractive: false,
});

const parameters = initialParameters();
let time = 0;
let playing = false;
let frameRequest = 0;
let playbackOrigin = 0;
let timeOrigin = 0;
let hasPlayedAutomatically = false;
let lastVisual = {};
let lastDrawKey = '';
let phase = 'lens';

const stage = new CameraStage(document.getElementById('stage'));

function snapshot() {
  return {
    t: time,
    time,
    duration: DURATION,
    playing,
    playback: playing ? 'playing' : time >= DURATION ? 'complete' : 'paused',
    mode: 'oneshot',
    aperture: parameters.aperture,
    fNumber: parameters.aperture,
    distance: parameters.distance,
    focusDistance: parameters.distance,
    focusLabel: Number.isFinite(parameters.distance) ? `${parameters.distance.toFixed(2)} m` : '∞',
    finish: parameters.finish,
    colorway: parameters.finish,
    section: parameters.section,
    sectionMode: parameters.section === 'right' ? 'right-cutaway' : 'left-cutaway',
    exploded: lastVisual.explodedAmount >= .5,
    explodedMode: lastVisual.explodedAmount >= .5 ? 'exploded' : 'assembled',
    explodedAmount: lastVisual.explodedAmount,
    phase,
    optical: { ...lastVisual },
  };
}

function draw() {
  const signature = [
    time, playing, parameters.aperture, String(parameters.distance), parameters.finish,
    parameters.section, String(parameters.explodedOverride), parameters.activeControl,
    parameters.focusInteractive,
  ].join('|');
  // Range elements emit input followed by change. Avoid re-rasterizing an
  // identical SVG when both events describe exactly the same scene state.
  if (signature === lastDrawKey) return;
  lastDrawKey = signature;
  phase = timelinePhase(time);
  lastVisual = stage.render({ time, ...parameters });
  controls.sync(snapshot(), lastVisual, phase);
}

function cancelFrame() {
  if (frameRequest) cancelAnimationFrame(frameRequest);
  frameRequest = 0;
}

function animationFrame(now) {
  frameRequest = 0;
  if (!playing) return;
  time = clamp(timeOrigin + (now - playbackOrigin) / 1000, 0, DURATION);
  if (time >= DURATION) {
    time = DURATION;
    playing = false;
  }
  draw();
  if (playing) frameRequest = requestAnimationFrame(animationFrame);
}

function pause() {
  hasPlayedAutomatically = true;
  playing = false;
  cancelFrame();
  draw();
}

function play() {
  cancelFrame();
  if (time >= DURATION) time = 0;
  playing = true;
  timeOrigin = time;
  playbackOrigin = performance.now();
  draw();
  frameRequest = requestAnimationFrame(animationFrame);
}

function applyTime(value, shouldPause = true) {
  hasPlayedAutomatically = true;
  if (shouldPause) {
    playing = false;
    cancelFrame();
  }
  const numeric = Number(value);
  time = Number.isFinite(numeric) ? clamp(numeric, 0, DURATION) : 0;
  draw();
  return time;
}

function setParameter(key, value) {
  if (!(key in parameters)) return;
  if (key === 'aperture') parameters.aperture = clamp(Number(value) || 2.5, 1.7, 16);
  else if (key === 'distance') {
    parameters.distance = value === Infinity ? Infinity : clamp(Number(value) || .7, .7, 50);
    if (Number(value) >= 50) parameters.distance = Infinity;
    parameters.focusInteractive = true;
  } else if (key === 'explodedOverride') parameters.explodedOverride = Boolean(value);
  else if (key === 'finish' && ['silver', 'black', 'champagne'].includes(value)) parameters.finish = value;
  else if (key === 'section' && ['left', 'right'].includes(value)) parameters.section = value;
  else if (key === 'activeControl' && ['aperture', 'focus'].includes(value)) parameters.activeControl = value;
  draw();
}

function reset() {
  playing = false;
  cancelFrame();
  Object.assign(parameters, initialParameters());
  time = 0;
  hasPlayedAutomatically = true;
  draw();
}

const controls = createControls({
  getState: snapshot,
  play,
  pause,
  setTime: applyTime,
  setParameter,
  reset,
});

window.renderAt = seconds => applyTime(seconds, true);
window.__getSceneState = () => snapshot();
window.__SCENE_READY__ = false;

draw();
window.__SCENE_READY__ = true;

// Armed, not autoplaying: the initial publication remains available for review.
// Play is the only wall-clock driver and always stops permanently at t = 8.
// Seeks and reset remain pure functions of scene state.

/** Pure optical math. Every function is deterministic and side-effect free. */
export const DURATION = 8;
export const F_STOPS = [1.7, 2, 2.5, 3.2, 4, 5.6, 8, 11, 16];
export const FOCUS_STOPS = [0.7, 1, 1.5, 3, 5, 10, Infinity];

export const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
export const lerp = (a, b, amount) => a + (b - a) * amount;
export const smooth = value => {
  const x = clamp(value, 0, 1);
  return x * x * (3 - 2 * x);
};
export const phase = (time, start, end) => smooth((time - start) / (end - start));

export function apertureRadius(fNumber) {
  const f = clamp(Number(fNumber) || 2.5, 1.7, 16);
  const normalized = (Math.log(16) - Math.log(f)) / (Math.log(16) - Math.log(1.7));
  return lerp(8, 51, normalized);
}

export function nearestStop(value, stops) {
  return stops.reduce((best, item, index) => {
    const bestDistance = Math.abs(stops[best] - value);
    return Math.abs(item - value) < bestDistance ? index : best;
  }, 0);
}

export function stepAperture(value, direction) {
  const index = nearestStop(value, F_STOPS);
  return F_STOPS[clamp(index + Math.sign(direction), 0, F_STOPS.length - 1)];
}

/** Logarithmic focus scale: 0 is 0.7 m, 1 is infinity. */
export function normalizedToDistance(value) {
  const n = clamp(Number(value) || 0, 0, 1);
  if (n >= 0.9995) return Infinity;
  return 0.7 * Math.exp(n * Math.log(50 / 0.7));
}

export function distanceToNormalized(distance) {
  if (!Number.isFinite(distance)) return 1;
  return clamp(Math.log(clamp(distance, 0.7, 50) / 0.7) / Math.log(50 / 0.7), 0, 1);
}

export function stepFocus(distance, direction) {
  const finiteDistance = Number.isFinite(distance) ? distance : 1000000;
  let index = FOCUS_STOPS.findIndex(item => Math.abs(item - finiteDistance) < 0.03);
  if (index < 0) {
    index = direction > 0
      ? FOCUS_STOPS.findIndex(item => item > finiteDistance)
      : FOCUS_STOPS.findLastIndex(item => item < finiteDistance);
    if (index < 0) index = direction > 0 ? FOCUS_STOPS.length - 1 : 0;
    return FOCUS_STOPS[index];
  }
  return FOCUS_STOPS[clamp(index + Math.sign(direction), 0, FOCUS_STOPS.length - 1)];
}

export function formatDistance(distance) {
  if (!Number.isFinite(distance)) return '∞';
  if (distance < 10) return distance.toFixed(distance < 1 ? 1 : 2).replace(/0$/, '');
  return Math.round(distance).toString();
}

export function focusTravel(distance) {
  // Near focus moves the floating group forward (towards the front element).
  return lerp(-17, 12, distanceToNormalized(distance));
}

export function timelinePhase(time) {
  if (time < 2) return 'lens';
  if (time < 4) return 'aperture';
  if (time < 6) return 'focus';
  return 'exposure';
}

export const FINISHES = {
  silver: {
    label: 'Silver / black', metalLight: '#e4e0d4', metalMid: '#a9a99f',
    metalDark: '#686d69', leather: '#252a28', edge: '#353a37', accent: '#862f35',
  },
  black: {
    label: 'All black', metalLight: '#555b57', metalMid: '#292e2c',
    metalDark: '#111514', leather: '#151a18', edge: '#0a0d0c', accent: '#a04448',
  },
  champagne: {
    label: 'Champagne titanium', metalLight: '#e0d2b5', metalMid: '#b5a485',
    metalDark: '#706855', leather: '#30332e', edge: '#4d4a3e', accent: '#8a3c3b',
  },
};

"""Small, dependency-free B-rep construction helpers (all dimensions in mm)."""
import math
import cadquery as cq


def as_shape(obj):
    return obj.val() if isinstance(obj, cq.Workplane) else obj


def compound(shapes):
    flat = []
    for shape in shapes:
        shape = as_shape(shape)
        solids = shape.Solids()
        flat.extend(solids if solids else [shape])
    return cq.Compound.makeCompound(flat)


def fuse_all(shapes):
    shapes = [as_shape(s) for s in shapes]
    result = shapes[0]
    for shape in shapes[1:]:
        result = result.fuse(shape)
    return result.clean()


def box_at(dx, dy, dz, cx, cy, cz, fillet_axis=None, radius=0.0):
    wp = cq.Workplane("XY").box(dx, dy, dz).translate((cx, cy, cz))
    if fillet_axis:
        wp = wp.edges(fillet_axis).fillet(radius)
    return wp.val()


def cylinder(radius, height, base, direction=(0.0, 0.0, 1.0)):
    return cq.Solid.makeCylinder(radius, height, cq.Vector(*base), cq.Vector(*direction))


def ring(outer, inner, height, base, direction=(0.0, 0.0, 1.0)):
    outer_s = cylinder(outer, height, base, direction)
    inner_s = cylinder(inner, height + 0.2, tuple(base[i] - 0.1 * direction[i] for i in range(3)), direction)
    return outer_s.cut(inner_s)


def xz_plane(y_back):
    """Local sketch X/Y map to global X/Z, positive extrusion goes toward -Y."""
    return cq.Plane(origin=(0.0, y_back, 0.0), xDir=(1.0, 0.0, 0.0), normal=(0.0, -1.0, 0.0))


def xz_polygon(points, y_back, depth):
    return cq.Workplane(xz_plane(y_back)).polyline(points).close().extrude(depth).val()


def xz_circle(center, radius, y_back, depth):
    return cq.Workplane(xz_plane(y_back)).center(center[0], center[1]).circle(radius).extrude(depth).val()


def xz_star(center, root_radius, tip_radius, count, y_back, depth, phase_deg=0.0):
    """Two flank points and two land points per tooth; a real closed toothed profile."""
    pts = []
    for i in range(int(count)):
        for fraction, radius in ((0.00, root_radius), (0.18, tip_radius), (0.66, tip_radius), (0.84, root_radius)):
            angle = math.radians(phase_deg + 360.0 * (i + fraction) / int(count))
            pts.append((center[0] + radius * math.cos(angle), center[1] + radius * math.sin(angle)))
    return xz_polygon(pts, y_back, depth)


def yz_star(center_x, center_y, center_z, root_radius, tip_radius, count, length):
    plane = cq.Plane(origin=(center_x, 0.0, 0.0), xDir=(0.0, 1.0, 0.0), normal=(1.0, 0.0, 0.0))
    pts = []
    for i in range(int(count)):
        for fraction, radius in ((0.0, root_radius), (0.22, tip_radius), (0.70, tip_radius), (0.88, root_radius)):
            angle = 2.0 * math.pi * (i + fraction) / int(count)
            pts.append((center_y + radius * math.cos(angle), center_z + radius * math.sin(angle)))
    return cq.Workplane(plane).polyline(pts).close().extrude(length).val()


def circle_hull(c1, c2, r1, r2, y_back, depth):
    """Exact double-disc convex hull using both external tangent quadrilateral edges."""
    dx, dz = c2[0] - c1[0], c2[1] - c1[1]
    dist = math.hypot(dx, dz)
    ux, uz = dx / dist, dz / dist
    vx, vz = -uz, ux
    a = (r1 - r2) / dist
    b = math.sqrt(max(0.0, 1.0 - a * a))
    normals = [(a * ux + b * vx, a * uz + b * vz), (a * ux - b * vx, a * uz - b * vz)]
    p1a = (c1[0] + r1 * normals[0][0], c1[1] + r1 * normals[0][1])
    p2a = (c2[0] + r2 * normals[0][0], c2[1] + r2 * normals[0][1])
    p2b = (c2[0] + r2 * normals[1][0], c2[1] + r2 * normals[1][1])
    p1b = (c1[0] + r1 * normals[1][0], c1[1] + r1 * normals[1][1])
    pieces = [xz_circle(c1, r1, y_back, depth), xz_circle(c2, r2, y_back, depth), xz_polygon([p1a, p2a, p2b, p1b], y_back, depth)]
    return fuse_all(pieces), normals


def capsule_slot_xz(p1, p2, radius, y_back, depth):
    dx, dz = p2[0] - p1[0], p2[1] - p1[1]
    length = math.hypot(dx, dz)
    nx, nz = -dz / length * radius, dx / length * radius
    quad = [(p1[0] + nx, p1[1] + nz), (p2[0] + nx, p2[1] + nz),
            (p2[0] - nx, p2[1] - nz), (p1[0] - nx, p1[1] - nz)]
    return fuse_all([xz_polygon(quad, y_back, depth), xz_circle(p1, radius, y_back, depth), xz_circle(p2, radius, y_back, depth)])

/* Four-Stroke DOHC Engine Workbench — Local Stylesheet (Zero CDN / Zero CSS Keyframes) */

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --bg-topbar: #151c23;
  --bg-stage: #1b232b;
  --bg-panel: #1b222a;
  --bg-panel-alt: #1e262f;
  --bg-rail: #171e26;
  --border-line: #2b3642;
  --ivory-bright: #ece4d0;
  --ivory-warm: #dfd5bb;
  --ivory-muted: #b5ae9c;
  --slate-muted: #93a0ab;
  --track-dark: #2c3540;
  --live-green: #4cd464;
  --focus-gold: #f5d88a;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background-color: var(--bg-topbar);
  color: var(--ivory-bright);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.workbench {
  display: grid;
  grid-template-rows: 42px minmax(0, 1fr) 86px;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
}

/* ==========================================================================
   1. Slim Dark Header
   ========================================================================== */
.topbar {
  display: grid;
  grid-template-columns: 120px 1fr 120px;
  align-items: center;
  padding: 0 18px;
  background-color: var(--bg-topbar);
  border-bottom: 1px solid var(--border-line);
}

.topbar-left {
  display: flex;
  align-items: center;
}

.topbar-title {
  margin: 0;
  text-align: center;
  font-size: 16.5px;
  font-weight: 500;
  letter-spacing: 0.25px;
  color: var(--ivory-bright);
  white-space: nowrap;
}

.topbar-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.live-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--live-green);
  box-shadow: 0 0 8px rgba(76, 212, 100, 0.65);
}

.live-label {
  font-size: 14px;
  font-weight: 500;
  color: #cfd8de;
}

/* ==========================================================================
   2. Main Workspace (Left ~2/3 Cutaway Stage + Right ~1/3 Diagnostics)
   ========================================================================== */
.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.92fr) minmax(410px, 1fr);
  min-height: 0;
